/**
 * Definition for singly-linked list.
 * class ListNode {
 *     val: number
 *     next: ListNode | null
 *     constructor(val?: number, next?: ListNode | null) {
 *         this.val = (val===undefined ? 0 : val)
 *         this.next = (next===undefined ? null : next)
 *     }
 * }
 */

function mergeKLists(lists: Array<ListNode | null>): ListNode | null {
  if (lists.length === 0) return null;

  // Сливаем списки парами, как в турнирной сетке:
  // step = 1: (0,1), (2,3), ...; step = 2: (0,2), (4,6), ...; и так далее.
  // Результат каждой пары кладём на место левого списка.
  for (let step = 1; step < lists.length; step *= 2) {
    for (let i = 0; i + step < lists.length; i += step * 2) {
      lists[i] = mergeTwo(lists[i], lists[i + step]);
    }
  }

  // После последнего раунда всё слито в lists[0]
  return lists[0];
}

// Классическое слияние двух отсортированных списков
function mergeTwo(a: ListNode | null, b: ListNode | null): ListNode | null {
  const dummy = new ListNode(0);
  let tail = dummy;

  while (a && b) {
    if (a.val <= b.val) {
      tail.next = a;
      a = a.next;
    } else {
      tail.next = b;
      b = b.next;
    }
    tail = tail.next;
  }

  // Остаток одного из списков пришиваем целиком
  tail.next = a ?? b;
  return dummy.next;
}

// Время: O(N log k) — log k раундов, в каждом все N узлов сливаются один раз
// Память: O(1) — только перевешиваем указатели
